// node gen-outline.js : writes 22-outline-underwear.feature and 23-outline-layers.feature (Virginie, 2026-10-23). Generated: do not edit by hand.
// Pass for both: wsl-deps.wdi-outline.map. The red outline top is the test def Venus_TestOutlineTop (Tests/Pickle/Mod/Defs).
const fs = require('fs');
const NAMES = ['M-Thin', 'M-Avg', 'M-Fat', 'M-Hulk', 'M-Kid', 'F-Thin', 'F-Avg', 'F-Fat', 'F-Hulk', 'F-Kid'];
const SPEC = {
  'M-Thin': ['male', 'Thin'], 'M-Avg': ['male', 'Male'], 'M-Fat': ['male', 'Fat'], 'M-Hulk': ['male', 'Hulk'], 'M-Kid': ['male', 'Child'],
  'F-Thin': ['female', 'Thin'], 'F-Avg': ['female', 'Female'], 'F-Fat': ['female', 'Fat'], 'F-Hulk': ['female', 'Hulk'], 'F-Kid': ['female', 'Child'],
};
const isKid = n => n.endsWith('Kid');
const x = n => 196 + 2 * (NAMES.indexOf(n) % 5);
const y = n => (n.startsWith('M') ? 186 : 184);
const T = "Nelim's Pickle Tools: ";
const REQ = '  @requires:wdi.realistic.bodies @requires:LoneKin.ChildrenWearAnything @requires:nelim.pickletools.screenshotstudio @requires:nelim.pickletools.colonistrace';

function setup(facing) {
  const o = ['    Given Nelim\'s Sanctuary: the animals are removed from the sanctuary "calm-zone-close"', '    And ' + T + 'the other colonists are out of frame'];
  for (const n of NAMES) {
    o.push('    And a colonist "' + n + '" exists');
    if (isKid(n)) o.push('    And "' + n + '" is 8 years old');
    o.push('    And "' + n + '" gender is ' + SPEC[n][0]);
    o.push('    And ' + T + '"' + n + '" body type is ' + SPEC[n][1]);
    o.push('    And ' + T + '"' + n + '" stands at (' + x(n) + ', ' + y(n) + ') facing ' + facing);
    o.push('    And I draft "' + n + '"');
  }
  return o;
}
const wear = (n, def, dye) => '    And ' + T + '"' + n + '" wears "' + def + '"' + (dye ? ' dyed rgb (' + dye + ')' : '');
const shot = label => ['    And Nelim\'s Sanctuary: I am at the sanctuary "calm-zone-close"', '    And ' + T + 'studio presentation mode is enabled',
  '    And I wait 120 ticks', '    And I take a screenshot "' + label + '"'];
const stripAll = () => NAMES.map(n => '    And I destroy the gear of "' + n + '"');
const underwear = (n, kind) => isKid(n) ? 'UnderWhere_Loincloth' : (kind === 'slip' ? 'UnderWhere_Panties' : 'UnderWhere_Boxers');
const TOP = 'Venus_TestOutlineTop', CREAM = '230, 224, 206', BLUE = '46, 74, 120';
const shirt = n => isKid(n) ? 'Apparel_KidShirt' : 'Apparel_BasicShirt';
const pants = n => isKid(n) ? 'Apparel_KidPants' : 'Apparel_Pants';

function underwearFeature() {
  const o = ['# The red outline top over underwear, from the front, the side and behind (Virginie, 2026-10-23). Generated by gen-outline.js.',
    '# Front, side and back: panties, then boxers (children wear the loincloth both times). Pass: wsl-deps.wdi-outline.map.',
    '@review @outline-underwear @timeout:900', 'Feature: the red outline top over underwear on every WDI silhouette', '', '  Background:', '    Given the save "Nelims-tribe" is loaded', '    And game speed is paused', ''];
  const plan = [['South', 'front', ['slip', 'boxers']], ['East', 'side', ['slip', 'boxers']], ['North', 'back', ['slip', 'boxers']]];
  for (const [facing, view, kinds] of plan) {
    o.push(REQ, '  Scenario: the red outline top over underwear, ' + view + ' (' + facing + ')');
    o.push(...setup(facing));
    for (const kind of kinds) {
      o.push(...stripAll());
      for (const n of NAMES) { o.push(wear(n, underwear(n, kind))); o.push(wear(n, TOP)); }
      o.push(...shot('outline underwear, ' + view + ', ' + kind));
    }
    o.push('');
  }
  return o.join('\n');
}

function layersFeature() {
  const o = ['# The red outline top bare, over a shirt, and over a shirt with trousers, from the front, the side and behind (Virginie, 2026-10-23).',
    '# Generated by gen-outline.js. The trousers are the translucent WDI ones of NativeWdiPants. Pass: wsl-deps.wdi-outline.map.',
    '@review @outline-layers @timeout:900', 'Feature: the red outline top worn over a shirt and trousers on every WDI silhouette', '', '  Background:', '    Given the save "Nelims-tribe" is loaded', '    And game speed is paused', ''];
  for (const [facing, view] of [['South', 'front'], ['East', 'side'], ['North', 'back']]) {
    o.push(REQ, '  Scenario: the red outline top bare, over a shirt, over a shirt and trousers, ' + view + ' (' + facing + ')');
    o.push(...setup(facing));
    o.push(...stripAll());
    for (const n of NAMES) o.push(wear(n, TOP));
    o.push(...shot('outline layers, ' + view + ', bare torso'));
    for (const n of NAMES) { o.push('    And I destroy the gear of "' + n + '"'); o.push(wear(n, shirt(n), CREAM)); o.push(wear(n, TOP)); }
    o.push(...shot('outline layers, ' + view + ', t-shirt'));
    for (const n of NAMES) { o.push('    And I destroy the gear of "' + n + '"'); o.push(wear(n, shirt(n), CREAM)); o.push(wear(n, pants(n), BLUE)); o.push(wear(n, TOP)); }
    o.push(...shot('outline layers, ' + view + ', t-shirt and trousers'));
    o.push('');
  }
  return o.join('\n');
}

// NPT, 2026-10-25: the jacket photo of the look gallery shows two grey strips and the belly through the middle. Bare torso, then
// bra + panties (UnderWhere), the jacket over each. Pass: wsl-deps.wdi-outline.map (no TailorMade: control) and wsl-deps.jacket-tm.map.
function jacketFeature() {
  const o = ['# The vanilla jacket on the ten WDI silhouettes, from the front: over a bare torso, then over bra and panties (NPT, 2026-10-25). Generated by gen-outline.js.',
    '# Pass: wsl-deps.wdi-outline.map (no TailorMade, the control) or wsl-deps.jacket-tm.map (with TailorMade).',
    '@review @jacket @timeout:900', 'Feature: the vanilla jacket on every WDI silhouette', '', '  Background:', '    Given the save "Nelims-tribe" is loaded', '    And game speed is paused', ''];
  o.push(REQ, '  Scenario: the jacket over a bare torso, then over bra and panties (South)');
  o.push(...setup('South'));
  o.push(...stripAll());
  for (const n of NAMES) if (!isKid(n)) o.push(wear(n, 'Apparel_Jacket'));
  o.push(...shot('jacket, bare torso'));
  for (const n of NAMES) { o.push('    And I destroy the gear of "' + n + '"'); if (!isKid(n)) { o.push(wear(n, n.startsWith('F') ? 'UnderWhere_Bra' : 'UnderWhere_Boxers')); if (n.startsWith('F')) o.push(wear(n, 'UnderWhere_Panties')); o.push(wear(n, 'Apparel_Jacket')); } }
  o.push(...shot('jacket, over underwear'));
  o.push('');
  return o.join('\n');
}

fs.writeFileSync(__dirname + '/24-jacket.feature', jacketFeature());
fs.writeFileSync(__dirname + '/22-outline-underwear.feature', underwearFeature());
fs.writeFileSync(__dirname + '/23-outline-layers.feature', layersFeature());
console.log('wrote 22-outline-underwear.feature and 23-outline-layers.feature');
